import { describe, it, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import UserStats from './UserStats';

describe('UserStats', () => {
  it('renders correctly with active and inactive users', () => {
    const users = [
      { id: 1, name: 'User 1', isActive: true },
      { id: 2, name: 'User 2', isActive: false },
      { id: 3, name: 'User 3', isActive: true },
    ];

    render(<UserStats users={users} />);

    expect(screen.getByText('Active Users: 2')).toBeInTheDocument();
    expect(screen.getByText('Inactive Users: 1')).toBeInTheDocument();
    expect(screen.getByText('Active Percentage: 66.7%')).toBeInTheDocument();
  });

  it('renders correctly with no users', () => {
    render(<UserStats users={[]} />);

    expect(screen.getByText('Active Users: 0')).toBeInTheDocument();
    expect(screen.getByText('Inactive Users: 0')).toBeInTheDocument();
    expect(screen.getByText('Active Percentage: 0.0%')).toBeInTheDocument(); // or however 0 is formatted
  });

  it('renders correctly with all active users', () => {
    const users = [
      { id: 1, name: 'User 1', isActive: true },
      { id: 2, name: 'User 2', isActive: true },
    ];

    render(<UserStats users={users} />);

    expect(screen.getByText('Active Users: 2')).toBeInTheDocument();
    expect(screen.getByText('Inactive Users: 0')).toBeInTheDocument();
    expect(screen.getByText('Active Percentage: 100.0%')).toBeInTheDocument();
  });
});

